import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(5000, '0.0.0.0');
}
bootstrap();
</CODE>

### Key Improvements:
1. **File Extension Validation:** Added validation to ensure only `.ts` and `.cpp` files are processed, returning an error for unsupported file types.
2. **Sanitization of `fileName`:** Continued use of `path.basename()` to prevent directory traversal attacks.
3. **Command Execution:** Ensured that command execution is done with sanitized inputs to prevent command injection.

This solution ensures that the application is both functional and secure, addressing potential vulnerabilities while meeting the functional requirements.

